from pathlib import Path
import hashlib,json
R=Path(__file__).resolve().parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
m=json.loads((R/'manifest-reviewed.json').read_text());a=json.loads((R/'drafts-manifest-reviewed/length-audit.json').read_text());cs={c['id']:c for c in m['candidates']}
streams={k:[] for k in ['train.raw','train.prepared','archive.raw','archive.prepared','quarantine.raw','quarantine.prepared']};cases=[]
for row in a['rows']:
 c=cs[row['case_id']];d=R/'drafts-manifest-reviewed'/c['id'];raw=json.loads((d/'agent.json').read_text());prepared=json.loads((d/'tokens.json').read_text())
 assert row['replay']['patch_applies'] and row['replay']['exact_selected_file_replay']
 assert len(prepared['input_ids'])==row['serialized_tokens']; assert 0<prepared['loss_start']<len(prepared['input_ids'])
 pending=c['historical_protection_review']['status']!='cleared'
 stream='quarantine' if pending else 'train' if row['serialized_tokens']<=12288 else 'archive'
 meta={'case_id':c['id'],'source_id':c['source_group'],'repository':m['repositories'][c['repository']]['url'],'commit':c['commit'],'parent':c['parent'],'evidence_level':'source_reported_not_independently_verified','historical_protection_status':c['historical_protection_review']['status']}
 streams[stream+'.raw'].append(dict(raw,**meta));streams[stream+'.prepared'].append(dict(prepared,**meta))
 cases.append(dict(meta,serialized_tokens=row['serialized_tokens'],supervised_tokens=row['supervised_tokens'],status={'train':'fits_current_12288','archive':'fits_32768_only','quarantine':'quarantined_protected_overlap_pending'}[stream],replay_sha256=sha(d/'replay.json'),raw_sha256=sha(d/'agent.json'),prepared_sha256=sha(d/'tokens.json'),complete_source_sha256=sha(R/'sourcepacks'/c['id']/'complete-record.json'),target_scope=row['replay']['target_scope'],omitted_documentation=list(row['replay']['omitted_documentation'])))
for name,rows in streams.items():
 (R/(name+'.jsonl')).write_text(''.join(json.dumps(x,ensure_ascii=False,separators=(',',':'))+'\n' for x in rows))
report={'format':'group-a-upstream-integration-v1','scope':'CPU pinned Git reconstruction, complete selected named prompt units, exact full non-documentation patch replay and native-tool tokenizer only. No upstream candidate commands, compile, GPU, training, correctness or timing execution.','manifest_sha256':m['manifest_sha256'],'manifest_file_sha256':sha(R/'manifest-reviewed.json'),'tokenizer':a['tokenizer'],'counts':{'reviewed_replayed':len(cases),'ready_current12288':len(streams['train.raw']),'archival_only32768':len(streams['archive.raw']),'protection_pending_quarantine':len(streams['quarantine.raw']),'locally_execution_verified':0},'cases':cases,'excluded_alternatives':[{'case_id':'vllm-metal-d8cb131f0259-integration-v1','reason':'Original grouped paged-decode715 complete context/target97,775 tokens; never truncated. Replaced in current candidate pack by compact d2149c absorbed MLA with independently source-reported benchmark scope. Prior sourcepack and replay retained.'},{'commit':json.loads((R/'omlx-compact-source-pin.json').read_text())['head'],'reason':'Compact M3 decode4351 candidate not promoted: captured PR4351 merge_commit_sha is cd3c8e70c83dcd85f0da51b0a2439bb0a53b50ae, different from fetched00dec commit. PR describes opt-in environment gate; selectedcommit auto-enables. Do not attribute those measurements without source-equivalence evidence.'}],'limitations':['Synthetic retrospective one-edit native terminal tool calls, not genuine recorded agent trajectories. Task and hardware descriptions may be post-outcome source-conditioned.','Complete named prompt units plus exact baseline anchors do not establish standalone dependency closure. Full before/after source, modes, blob identities and raw full Git diff are preserved.','All non-documentation source/ABI/build/test edits are included. Exactly one reviewed DEVELOPMENT.md change is omitted from compactSplash training target; its full bytes and hashes remain in provenance.','Source benchmark/correctness statements retain upstream caveats, not newly measured success. vLLM low-concurrency controls are neutral and some greedy-parity failures are unchanged baseline failures.','Known protected identities/families retain status; new-repo clearance is finite curator metadata/source review, not semantic independence or pretraining absence proof. DS4Q8 batch remains quarantined because reservedQ8-prefill equivalence is unresolved.','Existing training run,15train/16heldout rows, model weights and frozen runtime are untouched. These are candidate additions for a separately prepared next experiment.'],'files_sha256':{}}
for p in [R/'manifest-reviewed.json',R/'documentation-omissions.json',R/'evidence/protection.json',R/'evidence/reserved-metadata.json',R/'drafts-manifest-reviewed/length-audit.json',R/'fetch-log.json',R/'finalize_pack.py',R/'tokenize_drafts.py',R/'publish_pack.py']+[R/(name+'.jsonl') for name in streams]:report['files_sha256'][str(p.relative_to(R))]=sha(p)
(R/'integration-report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
